
(()=>{"use strict";
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const en=()=>document.documentElement.lang==="en"||document.documentElement.dir==="ltr",t=(he,e)=>en()?e:he;
async function api(path,opts={}){const init={credentials:"same-origin",...opts,headers:{...(opts.headers||{})}};if(opts.body&&!(opts.body instanceof FormData)){init.headers["Content-Type"]="application/json";init.body=JSON.stringify(opts.body)}const r=await fetch(path,init),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||t("הפעולה לא הושלמה","Action failed"));return d}
function toast(msg,bad=false){let x=$("#distribution-toast");if(!x){x=document.createElement("div");x.id="distribution-toast";x.setAttribute("role","status");x.style.cssText="position:fixed;z-index:100002;left:50%;bottom:18px;transform:translateX(-50%);max-width:min(560px,90vw);padding:12px 16px;border-radius:12px;color:white;background:#173a4d;box-shadow:0 12px 30px #0003";document.body.append(x)}x.style.background=bad?"#8f1d27":"#173a4d";x.textContent=msg;x.hidden=false;clearTimeout(x._timer);x._timer=setTimeout(()=>x.hidden=true,3500)}
function dialog(id,title){let d=$("#"+id);if(!d){d=document.createElement("dialog");d.id=id;d.className="modal modal-wide";document.body.append(d)}d.innerHTML='<button class="dialog-close" type="button" aria-label="'+t("סגירה","Close")+'">×</button><h2>'+esc(title)+'</h2><div class="distribution-body"></div>';$(".dialog-close",d).onclick=()=>d.close();return d}
function fmt(v){if(!v)return"";try{return new Intl.DateTimeFormat(en()?"en-GB":"he-IL",{dateStyle:"short",timeStyle:"short"}).format(new Date(v))}catch{return String(v)}}

async function openBranchSearch(){
 const d=dialog("branch-search-dialog",t("חיפוש סניפים ונקודות איסוף","Search branches and pickup points")),b=$(".distribution-body",d);
 b.innerHTML='<form id="branch-search-form" class="form-grid"><label>'+t("חיפוש","Search")+'<input name="q" type="search"></label><label>'+t("עיר","City")+'<input name="city" list="israel-cities"></label><label>'+t("דירוג מינימלי","Minimum rating")+'<select name="rating"><option value="0">'+t("הכול","Any")+'</option><option value="3">3+</option><option value="4">4+</option><option value="4.5">4.5+</option></select></label><label><input name="available" type="checkbox"> '+t("עם מלאי זמין","Available inventory")+'</label><label><input name="openNow" type="checkbox"> '+t("פתוח עכשיו","Open now")+'</label><label>'+t("מרחק מרבי","Maximum distance")+'<input name="distance" type="number" min="1" max="250" value="50"></label><button class="button button-secondary" type="button" data-use-location>'+t("מיון לפי המיקום שלי","Sort by my location")+'</button><button class="button button-primary">'+t("חיפוש סניפים","Search branches")+'</button></form><div id="branch-search-results" style="display:grid;gap:8px;margin-top:12px"></div>';
 d.showModal();const f=$("#branch-search-form",d),results=$("#branch-search-results",d);let coords=null;
 async function load(){const p=new URLSearchParams();if(f.q.value)p.set("q",f.q.value);if(f.city.value)p.set("city",f.city.value);if(f.rating.value!=="0")p.set("minRating",f.rating.value);if(f.available.checked)p.set("available","1");if(f.openNow.checked)p.set("openNow","1");if(coords){p.set("lat",coords.latitude);p.set("lon",coords.longitude);p.set("maxDistance",f.distance.value||50)}results.innerHTML="<p>"+t("טוענים...","Loading...")+"</p>";try{const x=await api("/api/search/branches?"+p);results.innerHTML=(x.branches||[]).map(r=>'<article class="dashboard-row"><div><strong>'+esc(r.name)+' · '+esc(r.organization_name)+'</strong><p>'+esc(r.address)+' · '+esc(r.city)+'</p><small>'+(r.rating?'⭐ '+esc(r.rating)+' ('+Number(r.reviewCount||0)+') · ':'')+t("יחידות זמינות","Available units")+': '+Number(r.availableUnits||0)+(r.distanceKm!=null?' · '+esc(r.distanceKm)+' km':'')+(r.openNow===true?' · '+t("פתוח עכשיו","Open now"):r.openNow===false?' · '+t("סגור עכשיו","Closed now"):'')+'</small></div><div class="dashboard-row-actions">'+(r.latitude!=null&&r.longitude!=null?'<a class="button button-secondary button-small" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(r.latitude+","+r.longitude)+'">Google Maps</a><a class="button button-secondary button-small" target="_blank" rel="noopener" href="https://waze.com/ul?ll='+encodeURIComponent(r.latitude+","+r.longitude)+'&navigate=yes">Waze</a>':'')+'</div></article>').join("")||"<p>"+t("לא נמצאו סניפים תואמים.","No matching branches found.")+"</p>"}catch(e){results.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}}
 f.onsubmit=e=>{e.preventDefault();load()};$("[data-use-location]",d).onclick=()=>{if(!navigator.geolocation){toast(t("המכשיר אינו תומך במיקום","Location is not supported"),true);return}navigator.geolocation.getCurrentPosition(pos=>{coords=pos.coords;toast(t("המיקום נוסף לחיפוש","Location added"));load()},()=>toast(t("לא התקבלה הרשאת מיקום","Location permission was not granted"),true),{enableHighAccuracy:false,timeout:7000,maximumAge:300000})};await load()
}
function installBranchSearchButton(){const controls=$(".catalog-controls");if(!controls||controls.querySelector("[data-search-branches]"))return;const b=document.createElement("button");b.type="button";b.className="filter-button";b.dataset.searchBranches="1";b.textContent=t("סניפים","Branches");b.onclick=openBranchSearch;controls.prepend(b)}

async function openAdminSupport(){
 const d=dialog("admin-support-center",t("מרכז תמיכה","Support center")),b=$(".distribution-body",d);d.showModal();
 b.innerHTML='<form id="admin-support-filter" class="form-grid"><label>'+t("חיפוש","Search")+'<input name="q" type="search"></label><label>'+t("סטטוס","Status")+'<select name="status"><option value="">'+t("הכול","All")+'</option><option>open</option><option>reopened</option><option>waiting</option><option>closed</option></select></label><label>'+t("עדיפות","Priority")+'<select name="priority"><option value="">'+t("הכול","All")+'</option><option>urgent</option><option>high</option><option>normal</option><option>low</option></select></label><button class="button button-primary">'+t("סינון","Filter")+'</button></form><div id="admin-support-list" style="display:grid;gap:8px;margin-top:12px"></div>';
 const f=$("#admin-support-filter",d),list=$("#admin-support-list",d);
 async function load(){const p=new URLSearchParams();if(f.q.value)p.set("q",f.q.value);if(f.status.value)p.set("status",f.status.value);if(f.priority.value)p.set("priority",f.priority.value);list.innerHTML="<p>"+t("טוענים...","Loading...")+"</p>";try{const x=await api("/api/admin/support-tickets?"+p);list.innerHTML=(x.tickets||[]).map(r=>'<button type="button" class="dashboard-row" data-admin-ticket="'+esc(r.id)+'"><div><strong>#'+esc(r.ticket_number)+' · '+esc(r.subject)+'</strong><p>'+esc(r.name)+' · '+esc(r.email)+'</p><small>'+esc(r.status)+' · '+esc(r.priority)+' · '+Number(r.message_count||0)+' '+t("הודעות","messages")+' · '+esc(fmt(r.updated_at))+'</small></div></button>').join("")||"<p>"+t("אין פניות תואמות.","No matching tickets.")+"</p>";$$("[data-admin-ticket]",list).forEach(x=>x.onclick=()=>openAdminTicket(x.dataset.adminTicket,load))}catch(e){list.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}}f.onsubmit=e=>{e.preventDefault();load()};await load()
}
async function openAdminTicket(id,onDone){
 const d=dialog("admin-ticket-detail",t("טיפול בפניית תמיכה","Handle support ticket")),b=$(".distribution-body",d);b.innerHTML="<p>"+t("טוענים...","Loading...")+"</p>";d.showModal();
 async function render(){try{const [x,a]=await Promise.all([api("/api/admin/support-tickets/"+encodeURIComponent(id)),api("/api/admin/support/admins")]),r=x.ticket;b.innerHTML='<h3>#'+esc(r.ticket_number)+' · '+esc(r.subject)+'</h3><p>'+esc(r.name)+' · '+esc(r.email)+'</p><form id="ticket-admin-meta" class="form-grid"><label>'+t("סטטוס","Status")+'<select name="status">'+["open","reopened","waiting","closed"].map(v=>'<option '+(r.status===v?"selected":"")+ '>'+v+'</option>').join("")+'</select></label><label>'+t("עדיפות","Priority")+'<select name="priority">'+["urgent","high","normal","low"].map(v=>'<option '+(r.priority===v?"selected":"")+ '>'+v+'</option>').join("")+'</select></label><label>'+t("הקצאה","Assign")+'<select name="assigned"><option value="">'+t("ללא הקצאה","Unassigned")+'</option>'+(a.admins||[]).map(u=>'<option value="'+esc(u.id)+'" '+(r.assigned_to===u.id?"selected":"")+'>'+esc(u.full_name)+'</option>').join("")+'</select></label><button class="button button-secondary">'+t("שמירת ניהול","Save")+'</button></form><div style="display:grid;gap:8px;margin:12px 0">'+(x.messages||[]).map(m=>'<article class="dashboard-row"><div><strong>'+esc(m.fromSupport?t("צוות התמיכה","Support"):m.full_name||r.name)+'</strong><p>'+esc(m.body)+'</p><small>'+esc(fmt(m.created_at))+'</small></div></article>').join("")+'</div><form id="ticket-admin-reply" class="stack-form"><label>'+t("תגובה","Reply")+'<textarea name="message" maxlength="2000" required></textarea></label><button class="button button-primary">'+t("שליחת תגובה","Send reply")+'</button></form>';
 $("#ticket-admin-meta",d).onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{await api("/api/admin/support-tickets/"+encodeURIComponent(id),{method:"PATCH",body:{status:f.status.value,priority:f.priority.value,assignedTo:f.assigned.value||null}});toast(t("הפנייה עודכנה","Ticket updated"));await render();if(onDone)await onDone()}catch(err){toast(err.message,true)}};
 $("#ticket-admin-reply",d).onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{await api("/api/admin/support-tickets/"+encodeURIComponent(id)+"/messages",{method:"POST",body:{message:f.message.value}});toast(t("התגובה נשלחה","Reply sent"));await render();if(onDone)await onDone()}catch(err){toast(err.message,true)}}}catch(e){b.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}}await render()
}
async function openReleaseReadiness(){
 const d=dialog("release-readiness-dialog",t("מוכנות להפצה","Release readiness")),b=$(".distribution-body",d);d.showModal();
 async function load(){b.innerHTML="<p>"+t("טוענים...","Loading...")+"</p>";try{const x=await api("/api/admin/release-readiness"),labels={email:t("שליחת אימייל","Email delivery"),encryption:t("הצפנת מידע","Data encryption"),turnstile:"Turnstile",push:"Web Push",aiModeration:t("סינון תמונות AI","AI image moderation"),separateBackupStorage:t("אחסון גיבוי נפרד","Separate backup storage"),recentBackup:t("גיבוי עדכני","Recent backup"),recentRestoreDrill:t("בדיקת שחזור תקופתית","Recent restore drill"),serverErrors:t("תקלות שרת פתוחות","Open server errors"),openAlerts:t("התראות מערכת פתוחות","Open system alerts"),urgentSupport:t("פניות דחופות","Urgent support")};
 const checks=x.checks||{},bools=["email","encryption","turnstile","push","aiModeration","separateBackupStorage","recentBackup","recentRestoreDrill"];
 b.innerHTML='<div class="dashboard-empty"><strong>'+t("סטטוס","Status")+': '+esc(x.status)+'</strong><p>'+t("חסמים","Blockers")+': '+esc((x.blockers||[]).join(", ")||t("אין","none"))+' · '+t("אזהרות","Warnings")+': '+esc((x.warnings||[]).join(", ")||t("אין","none"))+'</p></div><div style="display:grid;gap:8px">'+bools.map(k=>'<article class="dashboard-row"><div><strong>'+esc(labels[k]||k)+'</strong></div><span class="status-chip '+(checks[k]?"active":"")+'">'+(checks[k]?t("מוכן","Ready"):t("חסר","Missing"))+'</span></article>').join("")+'<article class="dashboard-row"><div><strong>'+esc(labels.serverErrors)+'</strong></div><span>'+Number(checks.openServerErrors24h||0)+'</span></article><article class="dashboard-row"><div><strong>'+esc(labels.openAlerts)+'</strong></div><span>'+Number(checks.openAlerts||0)+'</span></article><article class="dashboard-row"><div><strong>'+esc(labels.urgentSupport)+'</strong></div><span>'+Number(checks.urgentSupport||0)+'</span></article></div><div class="dashboard-row-actions" style="margin-top:12px">'+(x.latestBackup?.id?'<button class="button button-primary" data-run-restore-drill="'+esc(x.latestBackup.id)+'">'+t("הרצת בדיקת שחזור","Run restore drill")+'</button>':'')+'<button class="button button-secondary" data-test-alert>'+t("בדיקת התראת מנהל","Test admin alert")+'</button></div>'+(x.latestRestoreDrill?'<p><small>'+t("בדיקת שחזור אחרונה","Latest restore drill")+': '+esc(x.latestRestoreDrill.status)+' · '+esc(fmt(x.latestRestoreDrill.finished_at||x.latestRestoreDrill.started_at))+'</small></p>':"");
 $("[data-run-restore-drill]",d)?.addEventListener("click",async e=>{try{e.currentTarget.disabled=true;const r=await api("/api/admin/backups/"+encodeURIComponent(e.currentTarget.dataset.runRestoreDrill)+"/restore-drill",{method:"POST",body:{}});toast(t("בדיקת השחזור הסתיימה בהצלחה","Restore drill completed successfully"));await load()}catch(err){toast(err.message,true)}});
 $("[data-test-alert]",d)?.addEventListener("click",async()=>{try{const r=await api("/api/admin/release-readiness/test-alert",{method:"POST",body:{}});toast(r.delivery?.sent?t("התראת הבדיקה נשלחה","Test alert sent"):t("ההתראה נוצרה אך שירות האימייל אינו מוגדר","Alert created but email is not configured"),!r.delivery?.sent)}catch(err){toast(err.message,true)}})
 }catch(e){b.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}}await load()
}
async function openServerErrors(){
 const d=dialog("server-errors-dialog",t("תקלות שרת","Server errors")),b=$(".distribution-body",d);d.showModal();
 async function load(){b.innerHTML="<p>"+t("טוענים...","Loading...")+"</p>";try{const x=await api("/api/admin/server-errors");b.innerHTML=(x.errors||[]).map(r=>'<article class="dashboard-row"><div><strong>'+esc(r.path)+' · '+esc(r.method||"")+'</strong><p>'+esc(r.message)+'</p><small>'+esc(fmt(r.created_at))+' · '+esc(r.request_id)+'</small></div><button class="button button-secondary button-small" data-resolve-server-error="'+esc(r.id)+'">'+t("טופל","Resolve")+'</button></article>').join("")||"<p>"+t("אין תקלות פתוחות.","No open errors.")+"</p>";$$("[data-resolve-server-error]",d).forEach(x=>x.onclick=async()=>{try{await api("/api/admin/server-errors",{method:"PATCH",body:{id:x.dataset.resolveServerError}});toast(t("התקלה סומנה כטופלה","Error resolved"));await load()}catch(e){toast(e.message,true)}})}catch(e){b.innerHTML='<p role="alert">'+esc(e.message)+'</p>'}}await load()
}
function installAdminTools(){const tab=$("#admin-tab"),actions=$("#dashboard-view .dashboard-actions");if(!tab||tab.hidden||!actions)return;if(!actions.querySelector("[data-admin-support-center]")){const b=document.createElement("button");b.type="button";b.className="button button-secondary";b.dataset.adminSupportCenter="1";b.textContent=t("מרכז תמיכה","Support center");b.onclick=openAdminSupport;actions.prepend(b)}if(!actions.querySelector("[data-server-errors]")){const b=document.createElement("button");b.type="button";b.className="button button-secondary";b.dataset.serverErrors="1";b.textContent=t("תקלות שרת","Server errors");b.onclick=openServerErrors;actions.prepend(b)}if(!actions.querySelector("[data-release-readiness]")){const b=document.createElement("button");b.type="button";b.className="button button-secondary";b.dataset.releaseReadiness="1";b.textContent=t("מוכנות להפצה","Release readiness");b.onclick=openReleaseReadiness;actions.prepend(b)}}
function init(){const obs=new MutationObserver(()=>{installBranchSearchButton();installAdminTools()});obs.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:["hidden","lang","dir"]});installBranchSearchButton();installAdminTools()}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init,{once:true});else init();
})();
